    Tectonic is not installed, or compilation fails/times out, the caller is
    expected to fall back to storing the original TikZ source.
    """

    def __init__(
        self, timeout: float = 60.0, allow_shell_escape: bool = True
    ) -> None:
        self.timeout = timeout
        self.allow_shell_escape = allow_shell_escape

        located = shutil.which("tectonic")
        if located:
            self._is_available = True
            self.binary_path = Path(located)
        else:
            self._is_available = False
            self.binary_path = None
            _log.warning(
                "Tectonic binary not found. TikZ pictures will not be rendered to "
                "images. Install Tectonic and make it available on PATH to enable "
                "TikZ rendering."
            )

    def is_available(self) -> bool:
        return self._is_available

    def render(
        self,
        tikz_code: str,
        preamble: str = "",
        source_root: Optional[Path] = None,
    ) -> Optional[Any]:
        """Render a single ``tikzpicture`` and return a PIL image, or ``None``.

        ``None`` is returned when the engine is unavailable, when Tectonic times
        out or exits with an error, or when no PDF output is produced.
        """
        if not self._is_available or self.binary_path is None:
            return None

        sanitized_preamble = self._sanitize_preamble_for_tectonic(preamble)
        tex_document = self._build_tex_document(sanitized_preamble, tikz_code)

        with tempfile.TemporaryDirectory(prefix="docling_tikz_") as tmp:
            workdir = Path(tmp)
            tex_path = workdir / "docling_tikz.tex"
            tex_path.write_text(tex_document, encoding="utf-8")

            if source_root is not None:
                try:
                    self._stage_dependencies(
                        (preamble, tikz_code), Path(source_root), workdir
                    )
                except Exception as exc:  # staging must never break rendering
                    _log.debug("Failed to stage TikZ dependencies: %s", exc)

            cmd = self._build_command(tex_path, workdir)

            try:
                subprocess.run(
                    cmd,
                    cwd=str(workdir),
                    capture_output=True,
                    timeout=self.timeout,
                    check=True,
                )
